    CHECK(W.timer_registered && W.timer_released && W.timer_value == 11);
    CHECK(W.scared_off && W.lines == 1 && std::strcmp(W.line_text, "TEXT_QST_072_WASP_CHASE_FEMALE_ON_SAVED_10") == 0);
    CHECK(W.morality_given == 1 && W.saved_count == 2);
