    f.creature = V(5, 6, 7); f.seed = 1234u; f.flightCalls = 0; f.failFlightAt = -1; f.failHopAt = -1; f.hops = 0;
    f.groundBase = -100.0f; f.groundCalls = 0; f.lastRandomMax = 0; return f;
}

int main()
