            float moved_distance = moved.GetMagnitude();
            float step_length = step.GetMagnitude();
            if (!(moved_distance < distance) || !(step_length > 0.01f))
                break;
            float remaining = distance - moved_distance;
            if (can_continue) {
                if (remaining < step_length) {
