#pragma inline_depth()
            beam->m_OnhitEveryFrame = onhit_every_frame;
#pragma inline_depth(0)
            beams.push_back(beam);
#pragma inline_depth()
            targets.push_back(thing);
            result = true;
        }
    }
    return result;
}

