    {
        if (AwarenessTimer == 0.0f) DirectAwareness = false;
        float visibility = 1.0f;
        if (w->has_stealth) visibility = w->visibility;
        float ext = w->ext_radius * visibility;
        float sight = w->sight_radius * visibility;
