static bool IsSpace(char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; }

struct Parser {
    const char* text; unsigned long pos;
    void SkipWhitespace() { while (text[pos] && IsSpace(text[pos])) ++pos; }
    void SkipUntilWhitespace() { while (text[pos] && !IsSpace(text[pos])) ++pos; }
