enum { DEED_NONE = 0, DEED_ANNOYING_LARGE = 43, DEED_NICE_LARGE = 45 };
enum { TEXT_NONE = 0, TEXT_SCORED = 1, TEXT_BEATEN = 2, TEXT_FAILED = 3 };

struct Witness {
