C3DVector CEngineMap::PeekMapNormal(long x, long y) const
{
    float left = PeekLandscapeHeight(x - 1, y);
    float right = PeekLandscapeHeight(x + 1, y);
    float down = PeekLandscapeHeight(x, y - 1);
