                        CalculateSubPrimitiveRenderFlags(fading, material->IsTransparent(), material->IsBooleanAlpha(),
                                                         primitive.EnginePrimitiveFlags | 0x200, shadowed));
    }
    return RENDERED_OBJECT;
}

