        if (ParentThing->GetTC(&abilities))
            abilities->UnLockAbilitiyMutex();
        parent->FinishCurrentAction();
        parent->RemoveTC(TCI_TURNCOAT_SPELL);
        return;
    }
    case CWillButtonHelperTimer::RELEASED:
        parent->RemoveTC(TCI_TURNCOAT_SPELL);
        return;
    }
}

