    LeafData(f, version, 1, 9);
    Flags(f, version, true, false, version >= 6); Common(f, true, 0, 0, 12.0f, 22.0f, 8);   // child 8: switchable AND blocked (version 6+)
    LeafData(f, version, 2, 3);
