        if (t.NoActionPoints != 2 || t.ActionPoints[0].x != 101.0f || t.ActionPoints[0].y != 202.0f || t.ActionPoints[1].x != 103.5f ||
            t.ActionPoints[1].y != 204.5f || t.ActionPoints[1].layer != 1) ok = false;
