            if (quad12->child[3] != quad5 || quad12->child[0] != t.Layers[1][1] || quad12->child[1] != t.Layers[0][2]) ok = false;
            if (!quad5->child[2] || quad5->child[2]->kind != (version >= 6 ? SWITCHABLE : LEAF)) ok = false;
