        CScopedVertexShaderConstantLayout layout(3);
        if (group.LandscapeDecal)
            RenderLandscapeDecalGroup(group, premultiplied_alpha, point_light_count);
        g_pEngineLightingManager->RestoreDefaultPrimitiveParameters();
    }
