            NEngineInternal::GPShaderRenderManager->SetUserVertexShaderConstant(2, left, bottom, 1.0f, 1.0f);
            NEngineInternal::GPShaderRenderManager->SetUserVertexShaderConstant(3, right, bottom, 1.0f, 1.0f);
