        target.AttachTarget(GlowTexture16->GetSurfaceLevel(0));
        NEngineInternal::GPDisplayManager->SetRenderTarget(target);
        NEngineInternal::GPShaderRenderManager->ApplyVertexShader(VertexShaderBlur, false);
