        NEngineInternal::GPShaderRenderManager->SetUserVertexShaderConstant(2, 1.0f / 32.0f, 0.0f, 1.0f, 1.0f);
        NEngineInternal::GPShaderRenderManager->SetUserVertexShaderConstant(3, 1.0f / 32.0f, 1.0f / 32.0f, 1.0f, 1.0f);
