template <class T> class vector {
public:
    T* Start;
    int Count;
    vector() : Start(0), Count(0) {}
    ~vector() { delete[] Start; }
    void resize(int n) { delete[] Start; Start = n ? new T[n] : 0; Count = n; }
    vector& operator=(const vector& other)
    {
        Record(VecKind<T>::value, this, &other);
        if (this != &other) {
            ++g_depth;
            resize(other.Count);
            for (int i = 0; i < Count; ++i) Start[i] = other.Start[i];
            --g_depth;
        }
        return *this;
    }
private:
    vector(const vector&);
};

class CResource {
public:
    long ResourceSize;
    CResource() : ResourceSize(0) {}
    virtual ~CResource() {}
    CResource& operator=(const CResource& other) { Record(K_RES, this, &other); ResourceSize = other.ResourceSize; return *this; }
};
