        if (title.GetLength() == 0) {
            titleParts.push_back(CWideString::NullString);
            titleParts.push_back(CWideString::NullString);
        } else {
            titleParts.push_back(bank.GetTextBySymbol(CCharString("TEXT_GUI_STATS_LABEL_") + CCharString("CALLED")));
