    CHECK(gActions.size() == 16 && gActions[4] == "PC_STATS_PERSONALITY_LIST.selected:249:SCROLL_DESCRIPTION_UP:25" && gActions[7] == "PC_STATS_PERSONALITY_LIST.inactive:245:SCROLL_DESCRIPTION_DOWN:25");
    CHECK(gActions.size() == 16 && gActions[8] == "SCROLL_STATS_PERSONALITY_VIEWPORT_UP.leftclicked:230:PC_STATS_PERSONALITY_VIEWPORT:6" && gActions[11] == "SCROLL_STATS_PERSONALITY_VIEWPORT_DOWN.leftheld:230:PC_STATS_PERSONALITY_VIEWPORT:7");
    CHECK(gActions.size() == 16 && gActions[12] == "PC_STATS_PERSONALITY_LIST.selected:245:SCROLL_STATS_PERSONALITY_VIEWPORT_UP:25" && gActions[15] == "PC_STATS_PERSONALITY_LIST.inactive:249:SCROLL_STATS_PERSONALITY_VIEWPORT_DOWN:25");
    CHECK(gSliders.size() == 4);
    if (gSliders.size() == 4) {
        const Slider& a = gSliders[0]; const Slider& b = gSliders[1]; const Slider& c = gSliders[2]; const Slider& d = gSliders[3];
        CHECK(a.label == "<TEXT_GUI_STATS_LABEL_RENOWN>" && a.x == 5 && a.y == 0 && a.level == h.GetRenownLevel() && a.maxLevel == h.GetRenownLevelMaxLevel() && a.value == (float)h.GetRenownLevel() + 0.25f && a.width == 275.0f && a.red == 1.0f && !a.flag);
        CHECK(b.label == "<TEXT_GUI_STATS_LABEL_ALIGNMENT>" && b.x == 5 && b.y == 30 && b.level == 0 && b.maxLevel == 14 && b.value == 3.5f && b.width == 285.0f && b.red == 0.8f && b.flag);
        CHECK(c.label == "<TEXT_GUI_STATS_LABEL_ATTRACTIVENESS>" && c.x == 285 && c.y == 0 && c.value == 62.5f);
        CHECK(d.label == "<TEXT_GUI_STATS_LABEL_SCARINESS>" && d.x == 285 && d.y == 30 && d.value == 37.5f);
    }

    // run 2: no title, no favourite ability, no tattoos, creatures, inventory or trophy games, no description buttons, no slider container
    Reset();
    gTitle = ""; gFavouriteAbility = -1; gTattoos = 0; gInventory = false; gGoodness = -0.5f; gOverride[OFF_NumTrophyGamePlayed] = 0;
    gMissing.push_back("SCROLL_DESCRIPTION_UP"); gMissing.push_back("SCROLL_DESCRIPTION_DOWN"); gMissing.push_back("PC_STATS_EXP_STATIC_SLIDER_CONTAINER_NOT_SCROLLING");
    r = Run(stats, false);
    CHECK(r && gParts.size() == 4 && gParts[0] == "renown" && gParts[1] == "class" && gParts[2] == "" && gParts[3] == "");
    CHECK(!HasTitle("TATTOOS") && !HasTitle("CREATURESKILLED") && HasTitle("COMBAT") && gPage.size() == 22);
    CHECK(Has(L("FAVABILITY") + "<TEXT_GUI_STATS_LABEL_NONE>\n") && !Has("ability"));
    CHECK(!Has(L("TROPHIES")) && Has(L("TROPHIESUSED") + "0\n\n") && !Has(L("BESTTROPHY")));
    CHECK(gActions.size() == 12 && gSliders.empty() && gPositionChildren == 1);

    // run 3: two inventory items (one is not a trophy), evil hero, money above the recorded maximum
    Reset();
    gItems = 2; gGoodness = -0.5f; gOverride[OFF_Money] = 5000;
    r = Run(stats, true);
    CHECK(Has(L("TROPHIES") + Num(h.GetNumMountedTrophies() + 3) + "\n") && Has(L("MONEYMAX") + "5000\n"));
    CHECK(gSliders.size() == 4 && gSliders[1].red == 0.5f && gSliders[1].value == -3.5f);

    // run 4: no screen -- only the list and its actions
    Reset();
    gMissing.push_back("PC_STATS_PERSONALITY_SCREEN");
    r = Run(stats, true);
    CHECK(r && r->name == "PC_STATS_PERSONALITY_LIST" && gPage.empty() && gSliders.empty() && gActions.size() == 16 && gPositionChildren == 0);

    if (ok) std::printf("005d1f0c_TEST PASS\n"); else std::printf("005d1f0c_TEST FAIL\n");
    return ok ? 0 : 1;
}

