template <class T> static void Put(std::string& s, const std::vector<T>& v)
{
    long n = (long)v.size(); Put(s, n);
    for (long i = 0; i < n; i++) Put(s, v[i]);
}
static void Get(const std::string& s, size_t& at, long& v) { std::memcpy(&v, s.data() + at, sizeof v); at += sizeof v; }
static void Get(const std::string& s, size_t& at, float& v) { std::memcpy(&v, s.data() + at, sizeof v); at += sizeof v; }
