template <class T> static void Get(const std::string& s, size_t& at, std::vector<T>& v)
{
    long n; Get(s, at, n); v.clear();
    for (long i = 0; i < n; i++) { T item; Get(s, at, item); v.push_back(item); }
}

// ---- the recording persist context ----
template <class T> struct CPersistTraits { T DefaultVal; CPersistTraits() : DefaultVal() {} ~CPersistTraits() {} };
struct SEvent { std::string Name; const void* Member; int Kind; };

class CPersistContext {
public:
    enum { MODE_CLEAR, MODE_SAVE, MODE_LOAD };
    int Mode;
    std::vector<SEvent> Events;
    std::map<std::string, std::string> Store;

    explicit CPersistContext(int mode) : Mode(mode) {}
    void Note(const char* name, const void* member, int kind)
    {
        SEvent e; e.Name = name; e.Member = member; e.Kind = kind; Events.push_back(e);
    }
    template <class T> void Move(const char* name, T& value, const T& defaultVal)
    {
        if (Mode == MODE_CLEAR) value = defaultVal;
        else if (Mode == MODE_SAVE) { std::string s; Put(s, value); Store[name] = s; }
        else { size_t at = 0; Get(Store[name], at, value); }
    }
    template <class T> static T GetDefaultVal(T*) { CPersistTraits<T> traits; return traits.DefaultVal; }
    template <class T> void Transfer(const char* name, T& value, const T& defaultVal)
    {
        Note(name, &value, KindOf(&value)); Move(name, value, defaultVal);
    }
    template <class T> void Transfer(const char* name, T& value) { Transfer(name, value, GetDefaultVal((T*)0)); }
    template <class T> void TransferVector(const char* name, std::vector<T>& value)
    {
        Note(name, &value, VectorKindOf((T*)0)); Move(name, value, std::vector<T>());
    }
    template <class T> void TransferVectorOfSubComponents(const char* name, std::vector<T>& value)
    {
        Note(name, &value, SubKindOf((T*)0)); Move(name, value, std::vector<T>());
    }
};

