static void Fill(long& v, long i) { v = i + 1; }
static void Fill(float& v, long i) { v = (float)i + 0.5f; }
static void Fill(CDefString& v, long i) { v.TablePos = i + 7; }
static void Fill(CCharString& v, long i) { char t[32]; std::sprintf(t, "text%ld", i); v.Text = t; }
static void Fill(CConversation& v, long i) { v.Tag = i + 3; }
static void Fill(CFireHeartPatternDef& v, long i) { v.Tag = i + 3; }
static void Fill(CFeatDef& v, long i) { v.Tag = i + 3; }
static void Fill(CArenaRoundDef& v, long i) { v.Tag = i + 3; }
static void Fill(CHeroSoulsRoundDef& v, long i) { v.Tag = i + 3; }
template <class T> static void Fill(std::vector<T>& v, long i)
{
    v.clear();
    for (long k = 0; k < 1 + i % 3; k++) { T item; Fill(item, i + k); v.push_back(item); }
}
static bool Same(const long& a, const long& b) { return a == b; }
static bool Same(const float& a, const float& b) { return a == b; }
static bool Same(const CDefString& a, const CDefString& b) { return a.TablePos == b.TablePos; }
static bool Same(const CCharString& a, const CCharString& b) { return a.Text == b.Text; }
static bool Same(const CConversation& a, const CConversation& b) { return a.Tag == b.Tag; }
static bool Same(const CFireHeartPatternDef& a, const CFireHeartPatternDef& b) { return a.Tag == b.Tag; }
static bool Same(const CFeatDef& a, const CFeatDef& b) { return a.Tag == b.Tag; }
static bool Same(const CArenaRoundDef& a, const CArenaRoundDef& b) { return a.Tag == b.Tag; }
static bool Same(const CHeroSoulsRoundDef& a, const CHeroSoulsRoundDef& b) { return a.Tag == b.Tag; }
template <class T> static bool Same(const std::vector<T>& a, const std::vector<T>& b)
{
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); i++) if (!Same(a[i], b[i])) return false;
    return true;
}
template <class T> static bool IsDefault(const T& v) { return Same(v, T()); }

struct SFill { template <class T> void Do(T& a, T&, long i) { Fill(a, i); } };
struct SCount {
    long Members, Defaults, Equal;
    SCount() : Members(0), Defaults(0), Equal(0) {}
    template <class T> void Do(T& a, T& b, long) { Members++; if (IsDefault(a)) Defaults++; if (Same(a, b)) Equal++; }
};

